Cette cat&#233;gorie d’objets magiques rassemble diff&#233;rents types d’armes (arcs, &#233;p&#233;es, etc.) dot&#233;es de pouvoirs inhabituels qui ne ressemblent &#224; aucune propri&#233;t&#233; sp&#233;ciale d&#233;crite dans la rubrique pr&#233;c&#233;dente.&lt;br /&gt;&lt;br /&gt;Certaines armes magiques poss&#232;dent des propri&#233;t&#233;s qu’il faut activer par un &lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Relatives-Aux-Objets-Magiques.html#OBJETSAMOTDECOMMANDE&quot; title=&quot;R&#232;gles relatives aux objets magiques&quot;&gt;mot de commande&lt;/a&gt; ou qui fonctionnent automatiquement lorsqu’un personnage attaque avec.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Armes magiques sp&#233;cifiques&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Arme&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Balle-De-Signalisation.html&quot; title=&quot;Balle de signalisation&quot;&gt;Balle de Signalisation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Balle-Darme-&#192;-Feu-(Arme).html&quot; title=&quot;Balle d&amp;#39;arme &#224; feu (1)&quot;&gt;balle&lt;/a&gt; +1. N’inflige pas de d&#233;g&#226;ts au touch&#233;, mais inflige les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lueur-F&#233;erique.html&quot; title=&quot;Lueur f&#233;erique&quot;&gt;lueur f&#233;erique&lt;/a&gt;&lt;/i&gt; ainsi qu’un malus de -2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les attaques &#224; distance pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round(s)&lt;/a&gt; au touch&#233;.&lt;/td&gt;&lt;td&gt;100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;che-Endormante.html&quot; title=&quot;Fl&#232;che endormante&quot;&gt;Fl&#232;che Endormante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;che&lt;/a&gt; +1. Inflige des d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non-l&#233;taux&lt;/a&gt; et peut endormir sa cible au touch&#233;.&lt;/td&gt;&lt;td&gt;132 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bille-De-Poussi&#232;re.html&quot; title=&quot;Bille de poussi&#232;re&quot;&gt;Bille de Poussi&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Billes-De-Fronde-(Arme).html&quot; title=&quot;Billes de fronde (10)&quot;&gt;bille de fronde&lt;/a&gt; +1. Manifeste un nuage asphyxiant pendant 1d6 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round(s)&lt;/a&gt; sur la case de sa cible qui peut rendre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreux&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;aveugle&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;196 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;chette-Insaisissable.html&quot; title=&quot;Fl&#233;chette insaisissable&quot;&gt;Fl&#233;chette insaisissable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;chettes-Poids-Plume-(Arme).html&quot; title=&quot;Fl&#233;chettes poids-plume (10)&quot;&gt;fl&#233;chette poids-plume&lt;/a&gt; +1&lt;/i&gt;. Apr&#232;s avoir &#233;t&#233; tir&#233;e, le porteur peut rappeler les r&#233;sidus de l&#39;arme &#224; lui par une action rapide, afin de ne pas laisser de trace.&lt;/td&gt;&lt;td&gt;206 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Carreau-Denchev&#234;trement.html&quot; title=&quot;Carreau d&amp;#39;enchev&#234;trement&quot;&gt;Carreau d’Enchev&#234;trement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreau d&#39;arbal&#232;te&lt;/a&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Traqueuse.html&quot; title=&quot;traqueuse (propri&#233;t&#233;)&quot;&gt;traqueur&lt;/a&gt;&lt;/i&gt; +1. &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Enchev&#234;tr&#233;.html&quot; title=&quot;Enchev&#234;tr&#233;&quot;&gt;Enchev&#234;tre&lt;/a&gt; sa cible au touch&#233; (comme avec une &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html#Sacoche immobilisante&quot; title=&quot;Armes alchimiques&quot;&gt;sacoche immobilisante&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;226 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Carreau-Hurleur.html&quot; title=&quot;Carreau hurleur&quot;&gt;Carreau Hurleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreau d&#39;arbal&#232;te&lt;/a&gt; +2. Peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secouer&lt;/a&gt; les cr&#233;atures &#224; 6m ou moins de sa trajectoire.&lt;/td&gt;&lt;td&gt;267 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&